/*
  ход.js — ЛОГИКА мира-витрины: переходы, показ, посадка, очередь, чат.

  Чем отличается от соседей: здесь нет ни одного текста, который видит
  человек, и ни одного настроечного числа. Тексты берутся из мир.js,
  числа из настройки.js, оформление из стиль.e59c4df1.css и страницы.css.
  Это условие приёмки, оно проверяется работа/проверка.py.

  Шахматы живут отдельно, в шахматы.js: там своя библиотека и своя
  доска. Отсюда к ним обращаются через окно браузера.
*/

/*  Всё содержимое файла лежит в своей области: на одном адресе с
    миром живёт и сборка героя, а имена НАСТРОЙКИ, МИР и $ у них были
    одинаковые.                                                    */
window.ХОД = (function () {

'use strict';

const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;
const МИР       = window.МИР_ДАННЫЕ;

const $ = (ид) => document.getElementById(ид);

/* ═══ 1 · ГАММА ════════════════════════════════════════════════════
   Цвета брались у Телеграма, и ради этого страница тянула его скрипт
   с чужого сервера. Убрано: главный вход теперь браузер, а правило
   «ни одной ссылки на чужой сервер» — общее для всего проекта.
   Гамма целиком лежит в стиль.e59c4df1.css, одним набором на весь адрес.  */

/* ═══ 1.1 · ТЕКСТЫ ═════════════════════════════════════════════════
   Ни одной надписи в этом файле нет: у каждого места в разметке
   стоит метка data-т, а слова лежат в мир.js.

   Разметка теперь ОДНА на весь адрес, и метки в ней есть у обеих
   частей. Каждая часть расставляет свои: чужой ключ в её словаре не
   найдётся, и место остаётся как было.                            */

function расставитьТексты() {
  document.querySelectorAll('[data-т]').forEach((узел) => {
    const слово = МИР.тексты[узел.dataset.т];
    if (слово !== undefined) узел.textContent = слово;
  });
}

function подставить(шаблон, значения) {
  // имена подстановок русские, поэтому \w тут не годится: он покрывает
  // только латиницу и цифры, и шаблон оставался бы неразобранным
  return шаблон.replace(/\{([^{}]+)\}/g, (всё, ключ) =>
    (ключ in значения) ? значения[ключ] : всё);
}

/* ═══ 2 · СОСТОЯНИЕ ════════════════════════════════════════════════
   Всё, что человек делает, ложится сюда и сохраняется. Случайного при
   показе нет ничего: мир не должен меняться под человеком.          */

let герой = null;
let где = { страница: null, квартал: null, место: null, стол: null };
let мироеСостояние = { посадки: {}, очереди: {}, разговоры: {} };

function ключСтола(местоКлюч, столКлюч) { return местоКлюч + '/' + столКлюч; }

function достатьГероя() {
  try {
    const строка = localStorage.getItem(НАСТРОЙКИ.хранение.ключГероя);
    const запись = строка ? JSON.parse(строка) : null;
    return (запись && МИР.народы[запись.народ]) ? запись : null;
  } catch (е) { return null; }
}

function достатьСостояние() {
  try {
    const строка = localStorage.getItem(НАСТРОЙКИ.хранение.ключМира);
    const запись = строка ? JSON.parse(строка) : null;
    if (!запись || запись.версия !== НАСТРОЙКИ.хранение.версияЗаписи) return null;
    return запись.состояние;
  } catch (е) { return null; }
}

function сохранитьСостояние() {
  try {
    localStorage.setItem(НАСТРОЙКИ.хранение.ключМира, JSON.stringify({
      версия: НАСТРОЙКИ.хранение.версияЗаписи, состояние: мироеСостояние
    }));
  } catch (е) { /* память переполнена — мир всё равно на экране */ }
}

/* ═══ 3 · МЕЛОЧИ ═══════════════════════════════════════════════════ */

function знакНарода(ключНарода, размер) {
  const н = МИР.народы[ключНарода];
  if (!н) return '';
  return '<svg width="' + размер + '" height="' + размер + '" viewBox="' +
    НАСТРОЙКИ.знак.холст + '" fill="none" stroke="' + н.оттенок +
    '" stroke-width="' + НАСТРОЙКИ.знак.толщинаЛинии +
    '" stroke-linejoin="round">' + н.знак + '</svg>';
}

const местоПо = (ключ) => МИР.места.find((м) => м.ключ === ключ);
const обитатель = (ключ) => МИР.обитатели[ключ];

/* Кто сидит на месте за столом: заготовленный обитатель, ты или никто. */
function ктоСидит(местоКлюч, стол, номерМеста) {
  const моё = мироеСостояние.посадки[ключСтола(местоКлюч, стол.ключ)];
  if (моё === номерМеста) return { ты: true };
  const ключ = стол.сидят[номерМеста];
  return ключ ? { обитатель: обитатель(ключ), ключ: ключ } : null;
}

function занятоЗа(местоКлюч, стол) {
  let сколько = 0;
  for (let i = 0; i < стол.мест; i++) if (ктоСидит(местоКлюч, стол, i)) сколько++;
  return сколько;
}

/* ═══ 4 · ЭКРАНЫ ═══════════════════════════════════════════════════ */

const ЭКРАНЫ = ['э-ворота', 'э-карта', 'э-лавка', 'э-стол', 'э-дело'];

function показатьЭкран(ид) {
  ЭКРАНЫ.forEach((э) => { $(э).hidden = (э !== ид); });
  window.scrollTo(0, 0);
}

function окошко(заголовок, текст, кнопки) {
  $('окошко-заголовок').textContent = заголовок;
  $('окошко-текст').textContent = текст;
  $('окошко-кнопки').innerHTML = '';
  for (const [подпись, действие, главная] of кнопки) {
    const кн = document.createElement('button');
    кн.className = 'кн ' + (главная ? 'главная' : 'тихая');
    кн.textContent = подпись;
    кн.addEventListener('click', () => { закрытьОкошко(); if (действие) действие(); });
    $('окошко-кнопки').appendChild(кн);
  }
  $('завеса').hidden = false;
}

function закрытьОкошко() { $('завеса').hidden = true; }

// доска живёт отдельным файлом и зовёт окошко отсюда: своего у неё нет
window.ОКОШКО = окошко;

/* ═══ 5 · КАРТА МИРА ══════════════════════════════════════════════
   Двор снаружи живёт отдельным файлом карта.js: там своя геометрия,
   поиск пути и свой шаг кадра. Отсюда его только показывают. */

function показатьКарту() {
  показатьЭкран('э-карта');
  плашкаГероя();
  КАРТА.показать();
}

/*  ЛИЦО ГЕРОЯ УЗЛОМ, А НЕ СТРОКОЙ.

    Адрес картинки лежит в записи, а запись человек правит руками — и
    получает её от друга кодом переноса. В разметке ей делать нечего:
    склеенная строка превращает чужие данные в код.

    Знак народа — наша разметка из мир.js, её и вставляем разметкой. */
function лицоГероя(з, размер) {
  if (з.портрет) {
    const кадр = new Image();
    кадр.src = з.портрет;          // свойство узла, а не атрибут в строке
    кадр.alt = '';
    return кадр;
  }
  const знак = document.createElement('span');
  знак.className = НАСТРОЙКИ.имена.знак;
  знак.innerHTML = знакНарода(з.народ, размер);
  return знак;
}

/*  Подпись под лицом: имя и народ. Имя вводил человек, поэтому кладётся
    ТЕКСТОМ. Имя вида `<img src=x onerror=…>` иначе выполнилось бы как
    код — у самого шутника, у друга, которому он прислал героя, и у
    всех сразу, когда мир станет общим.                              */
function подписьГероя(з, народ, снаружи) {
  const обёртка = document.createElement(снаружи);
  const имя = document.createElement('b');
  имя.textContent = з.имя;
  const род = document.createElement('span');
  род.textContent = народ.имя.toLowerCase();
  обёртка.appendChild(имя);
  обёртка.appendChild(род);
  return обёртка;
}

/* Кто ты — в углу карты. Данные героя берутся из шага 1. */
function плашкаГероя() {
  const место = $('плашка-героя');
  if (!герой) { место.hidden = true; return; }
  место.hidden = false;
  место.textContent = '';
  место.appendChild(лицоГероя(герой, НАСТРОЙКИ.знак.вКарточке));
  место.appendChild(подписьГероя(герой, МИР.народы[герой.народ],
                                 НАСТРОЙКИ.имена.вПлашке));
}
function открытьМесто(ключМеста) {
  const м = местоПо(ключМеста);
  if (!м) return;
  const т = МИР.тексты;
  if (!м.лавка) {
    окошко(т.свободное_заголовок,
      подставить(т.место_цена, { цена: м.цена }) + ' — ' + т.свободное_текст,
      [[т.закрыть, null, true]]);
    return;
  }
  где.место = ключМеста;
  где.квартал = м.квартал;
  показатьЛавку();
}

function показатьЛавку() {
  const м = местоПо(где.место);
  const л = м.лавка;
  const т = МИР.тексты;
  const х = обитатель(л.хозяин);

  $('имя-лавки').textContent = л.название;
  $('хозяин-лавки').innerHTML = знакНарода(х.народ, НАСТРОЙКИ.знак.уОбитателя) +
    '<span>' + х.имя + '</span>';
  $('описание-лавки').textContent = л.описание;

  const естьСтолы = !л.закрыта && л.столы.length > 0;
  $('заголовок-столов').hidden = !естьСтолы;
  $('столы-лавки').hidden = !естьСтолы;
  $('лавка-примечание').textContent = л.закрыта ? т.лавка_закрыта
    : (л.столы.length ? '' : т.лавка_без_столов);

  if (естьСтолы) $('столы-лавки').innerHTML = л.столы.map((стол) => {
    const занято = занятоЗа(м.ключ, стол);
    const полон = занято >= стол.мест;
    const мойНомер = мироеСостояние.очереди[ключСтола(м.ключ, стол.ключ)];
    const сижу = мироеСостояние.посадки[ключСтола(м.ключ, стол.ключ)] !== undefined;

    const лица = [];
    for (let i = 0; i < стол.мест; i++) {
      const кто = ктоСидит(м.ключ, стол, i);
      if (!кто) continue;
      лица.push(кто.ты ? '<span>' + т.стол_ты + '</span>'
        : знакНарода(кто.обитатель.народ, НАСТРОЙКИ.знак.уОбитателя) +
          '<span>' + кто.обитатель.имя + '</span>');
    }

    // Кнопка обязана говорить правду. Полон и ты не в очереди — можно
    // встать в очередь. Уже в очереди — сесть нельзя, но посмотреть на
    // стол можно. Есть свободное место — садись.
    let подписьКнопки = т.стол_сесть;
    if (полон && !сижу) подписьКнопки = (мойНомер === undefined)
      ? т.стол_очередь : т.стол_смотреть;

    return '<div class="стол-строка">' +
      '<div class="о-столе"><b>' + стол.имя + '</b>' +
      '<div class="кто">' + подставить(т.занято_из, { есть: занято, всего: стол.мест }) +
      (лица.length ? ' · ' + лица.join(' ') : '') + '</div>' +
      '<div class="ставка">' + (стол.ставка > 0
        ? подставить(т.стол_ставка, { сколько: стол.ставка }) : т.стол_бесплатно) +
      (мойНомер !== undefined
        ? ' · ' + подставить(т.стол_вочереди, { номер: мойНомер }) : '') +
      '</div></div>' +
      '<button class="кн мелкая ' + (полон && !сижу ? 'тихая' : 'главная') +
      '" data-стол="' + стол.ключ + '">' + подписьКнопки + '</button></div>';
  }).join('');

  показатьЭкран('э-лавка');
}

/* ═══ 7 · СТОЛ ═════════════════════════════════════════════════════ */

function войтиЗаСтол(ключСтолаВЛавке) {
  где.стол = ключСтолаВЛавке;
  показатьСтол();
}

function столСейчас() {
  const м = местоПо(где.место);
  return м.лавка.столы.find((с) => с.ключ === где.стол);
}

function нарисоватьКруг() {
  const м = местоПо(где.место);
  const стол = столСейчас();
  const т = МИР.тексты;
  const н = НАСТРОЙКИ.стол;
  const круг = $('круг-стола');

  let разметка = '<div class="середина">' + стол.имя + '</div>';
  for (let i = 0; i < стол.мест; i++) {
    const кто = ктоСидит(м.ключ, стол, i);
    const угол = (н.уголНачалаДоля + i / стол.мест) * Math.PI * 2;
    const x = н.середина + Math.cos(угол) * н.радиусДоля;
    const y = н.середина + Math.sin(угол) * н.радиусДоля;
    const ходит = ходитЛи(i);

    let нутро, классы = ['место-за-столом'];
    if (ходит) классы.push('ходит');
    if (кто && кто.ты) {
      нутро = (герой && герой.портрет)
        ? '<img src="' + герой.портрет + '" alt="">'
        : знакНарода(герой ? герой.народ : стол.сидят[i], НАСТРОЙКИ.знак.вКарточке);
      разметка += подпись(классы, x, y, н, нутро, герой ? герой.имя : т.стол_ты);
    } else if (кто) {
      нутро = знакНарода(кто.обитатель.народ, НАСТРОЙКИ.знак.вКарточке);
      разметка += подпись(классы, x, y, н, нутро, кто.обитатель.имя);
    } else {
      классы.push('пустое');
      разметка += подпись(классы, x, y, н, '', т.стол_свободно, i);
    }
  }
  круг.innerHTML = разметка;

  function подпись(классы, x, y, н, нутро, текст, свободное) {
    return '<div class="' + классы.join(' ') + '" style="--х:' + x + ';--у:' + y +
      ';--размер:' + н.местоДоля + '"' +
      (свободное !== undefined ? ' data-сесть="' + свободное + '"' : '') + '>' +
      '<div class="лицо">' + нутро + '</div>' +
      '<div class="подпись">' + текст + '</div></div>';
  }
}

/* Чей сейчас ход. Для шахмат спрашиваем у доски, для прочих механик
   хода нет — их правила появятся позже. */
function ходитЛи(номерМеста) {
  const стол = столСейчас();
  if (стол.механика !== МИР.механики.шахматы || !window.ШАХМАТЫ) return false;
  return window.ШАХМАТЫ.чейХод() === номерМеста;
}

/* Доска и её библиотека грузятся только когда человек сел за стол.
   На карте они не нужны, а весят больше всего остального вместе.
   Не загрузилось — это и есть тот самый обрыв связи. */
async function подключитьШахматы() {
  if (window.ШАХМАТЫ) return true;
  try {
    await import('./шахматы.2cc33152.js');
    return !!window.ШАХМАТЫ;
  } catch (е) {
    return false;
  }
}

async function показатьСтол() {
  const стол = столСейчас();
  const т = МИР.тексты;
  $('имя-стола').textContent = стол.имя;
  нарисоватьКруг();
  нарисоватьРазговор();

  const поле = $('поле-игры');
  поле.innerHTML = '';
  $('стол-примечание').textContent = '';
  обновитьХод();
  показатьЭкран('э-стол');

  if (стол.механика !== МИР.механики.шахматы) {
    $('стол-примечание').textContent = т.стол_механика_позже;
    return;
  }

  $('стол-примечание').textContent = т.доска_грузится;
  const вышло = await подключитьШахматы();
  // пока грузилось, человек мог уйти к другому столу
  if (столСейчас() !== стол) return;
  if (!вышло) {
    $('стол-примечание').textContent = '';
    окошко(т.связь_пропала, т.ошибка_загрузки,
      [[т.связь_ещё_раз, () => location.reload(), true]]);
    return;
  }
  const м = местоПо(где.место);
  window.ШАХМАТЫ.поставить(поле, обновитьХод, ключСтола(м.ключ, стол.ключ));
  $('стол-примечание').textContent = т.шахматы_за_обоих;
  обновитьХод();
}

/* Зовётся доской после каждого хода: обновляет подпись и обводку. */
function обновитьХод() {
  const стол = столСейчас();
  const т = МИР.тексты;
  if (стол.механика !== МИР.механики.шахматы || !window.ШАХМАТЫ) {
    $('чей-ход').textContent = '';
    return;
  }
  const сторона = window.ШАХМАТЫ.чейХод() === 0 ? т.шахматы_белые : т.шахматы_чёрные;
  $('чей-ход').textContent = подставить(т.стол_ход, { кто: сторона });
  нарисоватьКруг();
}

function сесть(номерМеста) {
  const м = местоПо(где.место);
  const стол = столСейчас();
  мироеСостояние.посадки[ключСтола(м.ключ, стол.ключ)] = номерМеста;
  delete мироеСостояние.очереди[ключСтола(м.ключ, стол.ключ)];
  сохранитьСостояние();
  нарисоватьКруг();
}

function встатьВОчередь(стол) {
  const м = местоПо(где.место);
  const ключ = ключСтола(м.ключ, стол.ключ);
  if (мироеСостояние.очереди[ключ] === undefined)
    мироеСостояние.очереди[ключ] = стол.очередь + 1;
  сохранитьСостояние();
  показатьЛавку();
}

/* ═══ 8 · РАЗГОВОР ═════════════════════════════════════════════════
   Заготовленный. Отправка работает только у тебя — общего мира нет. */

function нарисоватьРазговор() {
  const м = местоПо(где.место);
  const ключ = ключСтола(м.ключ, где.стол);
  const мои = мироеСостояние.разговоры[ключ] || [];
  const все = МИР.разговор.map((р) => ({
    имя: обитатель(р.кто).имя, что: р.что, моя: false
  })).concat(мои.map((что) => ({
    имя: герой ? герой.имя : МИР.тексты.стол_ты, что: что, моя: true
  })));

  /*  РЕПЛИКИ КЛАДУТСЯ ТЕКСТОМ. И имя, и сама реплика введены
      человеком: он пишет их за столом, и они ложатся в память
      браузера. Склеенная строка сделала бы из них код.            */
  const разговор = $('разговор');
  разговор.textContent = '';
  for (const р of все) {
    const строка = document.createElement('div');
    строка.className = р.моя ? НАСТРОЙКИ.имена.репликаМоя : НАСТРОЙКИ.имена.реплика;
    const кто = document.createElement('b');
    кто.textContent = р.имя;
    строка.appendChild(кто);
    строка.appendChild(document.createTextNode(' ' + р.что));
    разговор.appendChild(строка);
  }
  $('разговор').scrollTop = $('разговор').scrollHeight;
}

function сказать() {
  const поле = $('поле-чата');
  const что = поле.value.trim();
  if (!что) return;
  const м = местоПо(где.место);
  const ключ = ключСтола(м.ключ, где.стол);
  if (!мироеСостояние.разговоры[ключ]) мироеСостояние.разговоры[ключ] = [];
  мироеСостояние.разговоры[ключ].push(что);
  поле.value = '';
  сохранитьСостояние();
  нарисоватьРазговор();
}

/* ═══ 9 · СОБЫТИЯ ══════════════════════════════════════════════════ */

function повеситьСобытия() {
  /*  Кнопку ворот вешает вэрн.be4d00a6.js: ворота показываются только когда
      героя нет, и значит она означает «создать героя», а не «войти».
      Раньше отсюда шли прямо в карту — с одним адресом это неверно. */

  $('к-из-лавки').addEventListener('click', показатьКарту);

  $('столы-лавки').addEventListener('click', (с) => {
    const узел = с.target.closest('[data-стол]');
    if (!узел) return;
    const м = местоПо(где.место);
    const стол = м.лавка.столы.find((э) => э.ключ === узел.dataset.стол);
    const полон = занятоЗа(м.ключ, стол) >= стол.мест;
    const ключ = ключСтола(м.ключ, стол.ключ);
    const сижу = мироеСостояние.посадки[ключ] !== undefined;
    const вОчереди = мироеСостояние.очереди[ключ] !== undefined;
    if (полон && !сижу && !вОчереди) { встатьВОчередь(стол); return; }
    войтиЗаСтол(стол.ключ);
  });

  $('к-из-стола').addEventListener('click', показатьЛавку);

  $('круг-стола').addEventListener('click', (с) => {
    const узел = с.target.closest('[data-сесть]');
    if (узел) сесть(Number(узел.dataset.сесть));
  });

  /* из лавки — обратно на карту, туда же, где герой и стоит */
  $('к-из-дела').addEventListener('click', показатьКарту);
  $('к-из-дела').textContent = window.ДЕЛА.тексты.назад;

  $('к-сказать').addEventListener('click', сказать);
  $('поле-чата').addEventListener('keydown', (с) => {
    if (с.key === 'Enter') сказать();
  });

  $('завеса').addEventListener('click', (с) => {
    if (с.target === $('завеса')) закрытьОкошко();
  });
}

/* ═══ 10 · ЗАПУСК ══════════════════════════════════════════════════ */

/*  Ворота показываются ТОЛЬКО когда героя нет: с героем человек
    попадает сразу в мир. Значит кнопка там означает «создать
    героя», а не «войти» — раньше она вела прямо в карту.         */
function показатьГерояВВоротах() {
  const т = МИР.тексты;
  if (!герой) {
    $('герой-полоска').hidden = true;
    $('к-войти').textContent = т.кнопка_создать;
    return;
  }
  const полоска = $('герой-полоска');
  полоска.hidden = false;
  полоска.textContent = '';
  полоска.appendChild(лицоГероя(герой, НАСТРОЙКИ.знак.вКарточке));
  полоска.appendChild(подписьГероя(герой, МИР.народы[герой.народ],
                                   НАСТРОЙКИ.имена.вВоротах));
}

function запуск() {
  расставитьТексты();

  герой = достатьГероя();
  const сохранённое = достатьСостояние();
  if (сохранённое) мироеСостояние = сохранённое;

  показатьГерояВВоротах();
  повеситьСобытия();
}

/*  Герой мог только что смениться в сборке — перечитываем запись и
    обновляем всё, где он виден. Перезагрузки страницы больше нет,
    само оно не обновится.                                         */
function перечитатьГероя() {
  герой = достатьГероя();
  показатьГерояВВоротах();
  if (!$('э-карта').hidden) плашкаГероя();
  КАРТА.перерисоватьГероя();
}

/* ═══ 11 · ЧТО ВИДНО СНАРУЖИ ═══════════════════════════════════════
   Переключением частей адреса заведует вэрн.be4d00a6.js.                  */

return {
  запуск: запуск,
  воВорота: () => показатьЭкран('э-ворота'),
  вДело: () => показатьЭкран('э-дело'),
  вКарту: показатьКарту,
  перечитатьГероя: перечитатьГероя,
  герой: () => герой,
  естьГерой: () => Boolean(герой)
};
})();
